package com.cxy.workbench;
import org.json.*;
import java.util.*;

/** Phone launcher layout in actual widget dp, never a scaled Mac canvas. */
final class MobileDevicePainter {
 static void text(CardPainter.Surface p,String s,float x,float y,float max,float size,int color,boolean bold){p.text(CardPainter.trim(p,s,max,size,bold),x,y,size,color,bold);}
 static void draw(CardPainter.Surface p,JSONObject data,String kind,long now,float w,float h,boolean dark){
  CardPainter.Theme t=new CardPainter.Theme(dark);p.rect(0,0,w,h,16,t.bg);
  JSONObject d=kind.equals("gateway")?data==null?null:data.optJSONObject("gateway"):DeviceText.sample(data,kind);
  CardPainter.icon(p,kind,14,15,21,CardPainter.BLUE);String title=kind.equals("gateway")?"家庭网关":kind.equals("overview")?"设备总览":DeviceText.title(kind);text(p,title,43,32,w-110,17,t.ink,true);
  if(d!=null&&!d.isNull("batteryPercent")&&kind.equals("mac")){String b=CardPainter.metric(d,"batteryPercent")+(d.optBoolean("onACPower")?" ⚡":"");text(p,b,w-72,31,58,12,t.muted,true);}
  if(kind.equals("overview")){overview(p,data,now,w,h,t);return;}
  float chipX=14;if(WidgetNetwork.lanDirect(d,now)){chipX+=badge(p,"局域网直连",chipX,43,CardPainter.BLUE,t.blueWash,t)+7;}String privateLabel=WidgetNetwork.privateLabel(d,now);badge(p,privateLabel,chipX,43,WidgetNetwork.privateConnected(privateLabel)?CardPainter.GREEN:t.muted,WidgetNetwork.privateConnected(privateLabel)?t.greenWash:(dark?0xff30333c:0xffe9eaf0),t);

  if(kind.equals("gateway")){gateway(p,DeviceText.sample(data,"linux"),now,w,h,t);return;}
  boolean fresh=DeviceText.hardwareFresh(d,now);float gap=7,tileW=(w-28-2*gap)/3;
  if(kind.equals("phone")){double used=0,total=0;JSONArray a=d==null?null:d.optJSONArray("disks");if(a!=null)for(int i=0;i<a.length();i++){JSONObject disk=a.optJSONObject(i);if(disk!=null){used+=disk.optDouble("used",0);total+=disk.optDouble("total",0);}}tile(p,14,70,tileW,"电量",CardPainter.metric(d,"batteryPercent"),CardPainter.BLUE,t);tile(p,14+tileW+gap,70,tileW,"内存",DeviceText.memory(d),CardPainter.TEAL,t);tile(p,14+2*(tileW+gap),70,tileW,"存储",total>0?CardMetrics.percent(used/total*100):"—",CardPainter.PURPLE,t);}else{tile(p,14,70,tileW,"CPU",CardPainter.metric(d,"cpu"),CardPainter.BLUE,t);tile(p,14+tileW+gap,70,tileW,"GPU",CardPainter.metric(d,"gpu"),CardPainter.TEAL,t);tile(p,14+2*(tileW+gap),70,tileW,"内存",DeviceText.memory(d),CardPainter.PURPLE,t);}
  String mem=CardPainter.bytes(DeviceText.number(d,"memoryUsed"))+" / "+CardPainter.bytes(DeviceText.number(d,"memoryTotal"));text(p,mem,14,136,w-28,11,t.muted,false);
  float mid=(w-28)/2;boolean hasSpeed=!kind.equals("phone")&&(!Double.isNaN(DeviceText.number(d,"download"))||!Double.isNaN(DeviceText.number(d,"upload")));boolean shortCard=h<230;float speedY=shortCard?125:145;if(shortCard)p.rect(0,123,w,21,0,t.bg);if(hasSpeed){p.rect(14,speedY,w-28,shortCard?25:30,10,t.panel);text(p,"↓ "+CardPainter.rate(DeviceText.number(d,"download"),fresh),24,speedY+18,mid-15,12,t.ink,true);text(p,"↑ "+CardPainter.rate(DeviceText.number(d,"upload"),fresh),24+mid,speedY+18,mid-15,12,t.ink,true);}
  JSONArray disks=d==null?null:d.optJSONArray("disks");int n=disks==null?0:disks.length();float y=hasSpeed?181:148;int columns=w>=280?2:1;int rows=(n+columns-1)/columns,fit=shortCard?0:Math.max(0,(int)((h-y-27)/36));int shown=Math.min(n,fit*columns);float dw=(w-28-(columns-1)*12)/columns;
  for(int i=0;i<shown;i++){JSONObject disk=disks.optJSONObject(i);if(disk==null)continue;float x=14+(i%columns)*(dw+12),dy=y+(i/columns)*36;String name=CardPainter.displayDisk(disk.optString("name","磁盘"));text(p,name,x,dy+10,dw,11,t.ink,true);String used=CardPainter.bytes(DeviceText.number(disk,"used"))+" / "+CardPainter.bytes(DeviceText.number(disk,"total"));text(p,used,x,dy+25,dw,11,t.muted,false);p.rect(x,dy+31,dw,4,2,t.faint);double total=DeviceText.number(disk,"total"),u=DeviceText.number(disk,"used");if(total>0&&!Double.isNaN(u))p.rect(x,dy+31,dw*(float)Math.max(0,Math.min(1,u/total)),4,2,CardPainter.BLUE);}
  if(n==0&&!shortCard)text(p,fresh?"磁盘数据未提供":"硬件数据待更新",14,200,w-28,11,t.muted,false);
  String footer=(n>shown?"另有 "+(n-shown)+" 盘 · 拉高/详情 · ":"")+(fresh?"":"未更新 · ")+CardPainter.time(Store.sampleMillis(d,"receivedAt"));text(p,footer,14,h-12,w-72,11,t.muted,false);p.text("↻",w-48,h-11,20,CardPainter.BLUE,false);p.text("↗",w-25,h-11,18,t.muted,false);
 }
 static float badge(CardPainter.Surface p,String s,float x,float y,int dot,int bg,CardPainter.Theme t){float width=p.measure(s,11,true)+27;p.rect(x,y,width,21,10,bg);p.circle(x+9,y+10.5f,3,dot);p.text(s,x+17,y+14.5f,11,t.ink,true);return width;}
 static void tile(CardPainter.Surface p,float x,float y,float w,String label,String value,int tint,CardPainter.Theme t){p.rect(x,y,w,51,12,t.panel);p.text(label,x+10,y+16,11,tint,true);text(p,value,x+10,y+41,w-20,23,t.ink,true);}
 static void overview(CardPainter.Surface p,JSONObject data,long now,float w,float h,CardPainter.Theme t){String[] ids={"mac","winpc","linux","phone"};float cw=(w-35)/2,rh=Math.max(74,(h-70)/2);for(int i=0;i<4;i++){JSONObject d=DeviceText.sample(data,ids[i]);float x=14+(i%2)*(cw+7),y=48+(i/2)*rh;p.rect(x,y,cw,rh-7,12,t.panel);text(p,DeviceText.title(ids[i]),x+10,y+21,cw-20,14,t.ink,true);text(p,"CPU "+CardPainter.metric(d,"cpu"),x+10,y+44,cw-20,12,t.ink,false);text(p,"内存 "+DeviceText.memory(d),x+10,y+63,cw-20,12,t.ink,false);if(rh>102)text(p,WidgetNetwork.privateLabel(d,now),x+10,y+85,cw-20,11,WidgetNetwork.privateConnected(WidgetNetwork.privateLabel(d,now))?CardPainter.GREEN:t.muted,false);}p.text("↗",w-25,h-10,18,t.muted,false);}
 static void gateway(CardPainter.Surface p,JSONObject linux,long now,float w,float h,CardPainter.Theme t){JSONObject proxy=linux==null?null:linux.optJSONObject("proxy");boolean fresh=DeviceText.hardwareFresh(linux,now)&&proxy!=null&&now-(long)(proxy.optDouble("sampledAtUnix",0)*1000)<18000;text(p,fresh?"当前出口":"上次出口",14,84,w-28,11,t.muted,false);text(p,proxy==null?"等待网关信息":proxy.optString("selected","未知"),14,106,w-28,16,t.ink,true);
  JSONArray nodes=proxy==null?null:proxy.optJSONArray("nodes");int n=nodes==null?0:nodes.length();float y=117,row=Math.max(61,Math.min(77,(h-145)/Math.max(1,n)));int fit=Math.max(0,(int)((h-145)/row));for(int i=0;i<Math.min(n,fit);i++){JSONObject node=nodes.optJSONObject(i);if(node==null)continue;p.rect(14,y,w-28,row-6,12,t.panel);text(p,(node.optBoolean("selected")?"当前 · ":"备用 · ")+node.optString("name","节点"),24,y+21,w-115,12,t.ink,true);boolean healthy=CardMetrics.nodeFresh(fresh,node.optString("health"),DeviceWidgets.probeTime(node),now);text(p,healthy&&!node.isNull("latencyMs")?String.format(Locale.CHINA,"%.0f ms",node.optDouble("latencyMs")):"—",w-98,y+25,74,18,CardPainter.BLUE,true);text(p,"HTTP探测 "+CardPainter.time(DeviceWidgets.probeTime(node)),24,y+43,w-48,11,t.muted,false);y+=row;}
  if(n>fit)text(p,"另有 "+(n-fit)+" 个节点 · 点开查看",14,h-31,w-28,11,t.muted,false);text(p,"采样 "+CardPainter.time(Store.sampleMillis(linux,"receivedAt")),14,h-12,w-72,11,t.muted,false);p.text("↻",w-48,h-11,20,CardPainter.BLUE,false);p.text("↗",w-25,h-11,18,t.muted,false);
 }
}
